/**
 * Monthly Incident Report Flow
 *
 * This flow automatically generates monthly incident reports:
 * 1. Runs on the 1st of every month at 8:00 AM
 * 2. Looks up all resolved incidents from the previous month
 * 3. Creates a summary report record in the task table
 * 4. Logs the report generation status
 *
 * The report includes:
 * - Total count of resolved incidents
 * - Report period (previous month start and end dates)
 * - Generation timestamp
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const monthlyIncidentReportFlow = Flow(
    {
        $id: Now.ID['monthly_incident_report_flow'],
        name: 'Monthly Incident Report Flow',
        description: 'Generates monthly summary reports for all resolved incidents from the previous month',
    },
    wfa.trigger(
        trigger.scheduled.monthly,
        { $id: Now.ID['monthly_report_trigger'] },
        {
            day_of_month: 1,
            time: Time({ hours: 8, minutes: 0, seconds: 0 }),
        }
    ),
    (params) => {
        // Step 1: Log the start of report generation
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_report_start'],
                annotation: 'Log report generation start',
            },
            {
                log_level: 'info',
                log_message: `Starting monthly incident report generation at ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}`,
            }
        )

        // Step 2: Look up all resolved incidents from the previous month
        const resolvedIncidents = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_resolved_incidents'],
                annotation: 'Retrieve all resolved incidents from previous month',
            },
            {
                table: 'incident',
                conditions: 'state=6^resolved_atRELATIVEGE@month@ago@1^resolved_atRELATIVELT@month@ago@0',
                max_results: 1000,
                sort_column: 'resolved_at',
                sort_type: 'sort_desc',
            }
        )

        // Step 3: Log the count of resolved incidents found
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_incident_count'],
                annotation: 'Log number of resolved incidents found',
            },
            {
                log_level: 'info',
                log_message: `Found ${wfa.dataPill(resolvedIncidents.Count, 'integer')} resolved incidents from previous month`,
            }
        )

        // Step 4: Create summary report record in task table
        const reportRecord = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_report_record'],
                annotation: 'Create monthly incident summary report record',
            },
            {
                table_name: 'task',
                values: TemplateValue({
                    short_description: `Monthly Incident Report - Resolved Incidents`,
                    description: `Monthly incident summary report for previous month. Total resolved incidents: ${wfa.dataPill(resolvedIncidents.Count, 'integer')}. Generated at: ${wfa.dataPill(params.trigger.run_start_date_time, 'datetime')}.`,
                    state: 1,
                    priority: 4,
                }),
            }
        )

        // Step 5: Log successful report creation
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_report_created'],
                annotation: 'Log successful report record creation',
            },
            {
                log_level: 'info',
                log_message: `Monthly incident report successfully created: ${wfa.dataPill(reportRecord.record, 'reference')} with ${wfa.dataPill(resolvedIncidents.Count, 'integer')} resolved incidents`,
            }
        )

        // Step 6: Send notification about report generation
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_report_notification'],
                annotation: 'Send notification about monthly report generation',
            },
            {
                record: `${wfa.dataPill(reportRecord.record, 'reference')}`,
                notification: 'monthly_incident_report_notification',
            }
        )
    }
)
